 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    objects = {}
    for color in colors:
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        objects[color] = cells
    top = min(r for cells in objects.values() for r,c in cells)
    out = [[0]*w for _ in range(h)]
    for color,cells in objects.items():
        obj_top = min(r for r,c in cells)
        for r,c in cells:
            nr = r + top - obj_top
            out[nr][c] = color
    return out
